-- 이번 확장 SQL의 신규 코드만 삭제합니다. 기존 SQUAT/PUSHUP/SHOULDER_PRESS는 포함하지 않습니다.
-- 참조 중인 운동은 아래 DELETE 조건에 의해 보존됩니다.
DELETE e FROM exercise e
LEFT JOIN workout_plan wp ON wp.exercise_id=e.exercise_id
LEFT JOIN workout_record wr ON wr.exercise_id=e.exercise_id
LEFT JOIN pt_assignment pa ON pa.exercise_id=e.exercise_id
WHERE e.exercise_code IN ('LEG_PRESS','LEG_EXTENSION','LEG_CURL','LUNGE','BULGARIAN_SPLIT_SQUAT','HIP_THRUST','ROMANIAN_DEADLIFT','CALF_RAISE','BENCH_PRESS','INCLINE_BENCH_PRESS','DUMBBELL_PRESS','CHEST_PRESS','CABLE_FLY','PEC_DECK_FLY','LAT_PULLDOWN','SEATED_ROW','BARBELL_ROW','ONE_ARM_DUMBBELL_ROW','PULLUP','DEADLIFT','LATERAL_RAISE','FRONT_RAISE','REAR_DELT_FLY','FACE_PULL','BARBELL_CURL','DUMBBELL_CURL','HAMMER_CURL','TRICEPS_PUSHDOWN','OVERHEAD_TRICEPS_EXTENSION','DIPS','PLANK','CRUNCH','LEG_RAISE','RUSSIAN_TWIST','MOUNTAIN_CLIMBER','TREADMILL','STATIONARY_BIKE','STEPMILL','ELLIPTICAL','ROWING_MACHINE')
AND wp.workout_plan_id IS NULL AND wr.workout_record_id IS NULL AND pa.assignment_id IS NULL;
SELECT exercise_code FROM exercise WHERE exercise_code IN ('LEG_PRESS','LEG_EXTENSION','LEG_CURL','LUNGE','BULGARIAN_SPLIT_SQUAT','HIP_THRUST','ROMANIAN_DEADLIFT','CALF_RAISE');
